import { Injectable, inject, signal } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable, catchError, map, of, switchMap, tap } from 'rxjs';
import { environment } from '../../environments/environment';
import { User, UserRole } from '../models/user.model';

export type { User, UserRole };

@Injectable({
  providedIn: 'root',
})
export class AuthService {
  private readonly http = inject(HttpClient);
  private readonly apiUrl = environment.apiUrl;
  readonly currentUser = signal<User | null>(null);
  readonly pendingVerificationEmail = signal<string | null>(null);
  readonly isAuthModalOpen = signal<boolean>(false);
  readonly sessionExpired = signal<boolean>(false);
  private csrfFetched = false;

  invalidateCsrf(): void {
    this.csrfFetched = false;
  }

  private getFullUrl(path: string): string {
    const cleanPath = path.startsWith('/') ? path.substring(1) : path;
    if (this.apiUrl.endsWith('/api') || this.apiUrl === '/api') {
      if (cleanPath.startsWith('api/')) {
        return `${this.apiUrl}/${cleanPath.substring(4)}`;
      }
    }
    return `${this.apiUrl}/${cleanPath}`;
  }

  defaultRouteFor(role: UserRole): string[] {
    return role === 'inversor'
      ? ['/inversores/autorizaciones']
      : ['/ejecutivos/dashboard'];
  }

  llaveMxRedirectUrl(): string {
    return this.getFullUrl('api/auth/llave-mx/redirect');
  }

  getCsrfCookie(): Observable<void> {
    if (this.csrfFetched) {
      return of(undefined);
    }
    
    const sanctumUrl = this.apiUrl.startsWith('http')
      ? (() => {
          const url = new URL(this.apiUrl);
          const basePath = url.pathname.replace(/\/api\/?$/, '').replace(/\/$/, '');
          return `${url.origin}${basePath}/sanctum/csrf-cookie`;
        })()
      : '/sanctum/csrf-cookie';

    return this.http.get<void>(sanctumUrl).pipe(
      tap(() => {
        this.csrfFetched = true;
      }),
      catchError((error) => {
        this.csrfFetched = false;
        console.error('Error fetching CSRF cookie', error);
        return of(undefined);
      })
    );
  }

  checkSession(): Observable<User | null> {
    return this.http.get<{ data: User }>(this.getFullUrl('api/user')).pipe(
      map((res) => {
        this.currentUser.set(res.data);
        return res.data;
      }),
      catchError(() => {
        this.currentUser.set(null);
        return of(null);
      })
    );
  }

  login(email: string, password: string): Observable<User> {
    return this.getCsrfCookie().pipe(
      switchMap(() =>
        this.http.post<{ data: User }>(this.getFullUrl('api/login'), {
          email,
          password,
        })
      ),
      map((res) => {
        this.currentUser.set(res.data);
        return res.data;
      })
    );
  }

  register(
    name: string,
    email: string,
    password: string,
    passwordConfirmation: string
  ): Observable<User> {
    return this.getCsrfCookie().pipe(
      switchMap(() =>
        this.http.post<{ data: User }>(this.getFullUrl('api/register'), {
          name,
          email,
          password,
          password_confirmation: passwordConfirmation,
        })
      ),
      map((res) => {
        return res.data;
      })
    );
  }

  logout(): Observable<void> {
    return this.http.post<void>(this.getFullUrl('api/logout'), {}).pipe(
      tap(() => {
        this.currentUser.set(null);
        this.invalidateCsrf();
      }),
      catchError((err) => {
        this.currentUser.set(null);
        this.invalidateCsrf();
        throw err;
      })
    );
  }

  forgotPassword(email: string): Observable<{ message: string }> {
    return this.getCsrfCookie().pipe(
      switchMap(() =>
        this.http.post<{ message: string }>(this.getFullUrl('api/forgot-password'), { email })
      )
    );
  }

  resetPassword(
    code: string,
    email: string,
    password: string,
    passwordConfirmation: string
  ): Observable<{ message: string }> {
    return this.getCsrfCookie().pipe(
      switchMap(() =>
        this.http.post<{ message: string }>(this.getFullUrl('api/reset-password'), {
          code,
          email,
          password,
          password_confirmation: passwordConfirmation,
        })
      )
    );
  }

  verifyEmail(email: string, code: string): Observable<{ message: string }> {
    return this.getCsrfCookie().pipe(
      switchMap(() =>
        this.http.post<{ message: string }>(this.getFullUrl('api/email/verify-code'), {
          email,
          code,
        })
      )
    );
  }

  resendVerification(email: string): Observable<{ message: string }> {
    return this.getCsrfCookie().pipe(
      switchMap(() =>
        this.http.post<{ message: string }>(this.getFullUrl('api/email/verification-notification'), { email })
      )
    );
  }

  openModal() {
    this.isAuthModalOpen.set(true);
    const trigger = document.createElement('button');
    trigger.setAttribute('data-bs-toggle', 'modal');
    trigger.setAttribute('data-bs-target', '#authModal');
    trigger.style.display = 'none';
    document.body.appendChild(trigger);
    trigger.click();
    trigger.remove();
  }

  closeModal() {
    if (!this.isAuthModalOpen()) {
      return;
    }
    this.isAuthModalOpen.set(false);
    
    const modalEl = document.getElementById('authModal');
    if (modalEl) {
      modalEl.classList.remove('show');
      modalEl.style.display = 'none';
      modalEl.setAttribute('aria-hidden', 'true');
      modalEl.removeAttribute('aria-modal');
      modalEl.removeAttribute('role');
    }

    document.querySelectorAll('.modal-backdrop').forEach(el => el.remove());
    document.body.classList.remove('modal-open');
    document.body.style.overflow = '';
    document.body.style.paddingRight = '';
  }
}
